// Component and page styles must use --he-* tokens only; raw colours belong in
// src/styles/tokens.css (generated by scripts/tokens/build-tokens.mjs).
//
// CSS under src/components and src/pages: no hex, rgb()/rgba(), hsl()/hsla(), hwb(), lab(),
// lch(), oklab(), oklch(), color(), light-dark(), and no named colours (`transparent`,
// `currentColor`, `inherit` are fine). `color-mix()` is allowed when every operand is a
// var(--he-*) (or `transparent`): that is how component CSS derives a tint without a raw value.
//
// Escape hatch: `/* tokens-ok */` on the line excuses a named-colour hit (an identifier that
// happens to be a colour word). Every use is printed, and a functional or hex colour literal
// on the same line still fails: the escape never admits a raw colour value.
//
// .tsx under src/components and src/pages: inline `style={{ ... }}` objects must not contain
// colour literals either.
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const scanDirs = ['src/components', 'src/pages'].map((d) => path.join(root, d));

// CSS Color 4 named colours (transparent/currentColor are keywords, allowed).
const NAMED = new Set(
  (
    'aliceblue antiquewhite aqua aquamarine azure beige bisque black blanchedalmond blue ' +
    'blueviolet brown burlywood cadetblue chartreuse chocolate coral cornflowerblue cornsilk ' +
    'crimson cyan darkblue darkcyan darkgoldenrod darkgray darkgreen darkgrey darkkhaki ' +
    'darkmagenta darkolivegreen darkorange darkorchid darkred darksalmon darkseagreen ' +
    'darkslateblue darkslategray darkslategrey darkturquoise darkviolet deeppink deepskyblue ' +
    'dimgray dimgrey dodgerblue firebrick floralwhite forestgreen fuchsia gainsboro ghostwhite ' +
    'gold goldenrod gray green greenyellow grey honeydew hotpink indianred indigo ivory khaki ' +
    'lavender lavenderblush lawngreen lemonchiffon lightblue lightcoral lightcyan ' +
    'lightgoldenrodyellow lightgray lightgreen lightgrey lightpink lightsalmon lightseagreen ' +
    'lightskyblue lightslategray lightslategrey lightsteelblue lightyellow lime limegreen linen ' +
    'magenta maroon mediumaquamarine mediumblue mediumorchid mediumpurple mediumseagreen ' +
    'mediumslateblue mediumspringgreen mediumturquoise mediumvioletred midnightblue mintcream ' +
    'mistyrose moccasin navajowhite navy oldlace olive olivedrab orange orangered orchid ' +
    'palegoldenrod palegreen paleturquoise palevioletred papayawhip peachpuff peru pink plum ' +
    'powderblue purple rebeccapurple red rosybrown royalblue saddlebrown salmon sandybrown ' +
    'seagreen seashell sienna silver skyblue slateblue slategray slategrey snow springgreen ' +
    'steelblue tan teal thistle tomato turquoise violet wheat white whitesmoke yellow yellowgreen'
  ).split(' '),
);

const LITERAL = /#[0-9a-fA-F]{3,8}\b|\b(?:rgba?|hsla?|hwb|oklch|oklab|lab|lch|color|light-dark)\(/;

/** Colour words used as whole identifiers (so `--he-white`, `.he-chip--red` do not count). */
const namedHits = (text) =>
  [...text.matchAll(/(?<![\w.#-])[a-zA-Z][\w-]*/g)].map((m) => m[0]).filter((w) => NAMED.has(w.toLowerCase()));

/** Bodies of every color-mix(...) on the line, balanced parentheses. */
const colorMixBodies = (line) => {
  const out = [];
  let i = line.indexOf('color-mix(');
  while (i >= 0) {
    let depth = 0;
    let j = i + 'color-mix'.length;
    for (; j < line.length; j++) {
      if (line[j] === '(') depth++;
      else if (line[j] === ')' && --depth === 0) break;
    }
    out.push(line.slice(i + 'color-mix('.length, j));
    i = line.indexOf('color-mix(', j);
  }
  return out;
};

/** Split on top-level commas only. */
const topLevelSplit = (s) => {
  const parts = [];
  let depth = 0;
  let cur = '';
  for (const ch of s) {
    if (ch === '(') depth++;
    if (ch === ')') depth--;
    if (ch === ',' && depth === 0) {
      parts.push(cur);
      cur = '';
    } else cur += ch;
  }
  parts.push(cur);
  return parts;
};

const badColorMix = (line) =>
  colorMixBodies(line).some((body) => {
    const [first, ...operands] = topLevelSplit(body);
    const ops = /^\s*in\s/.test(first) ? operands : [first, ...operands];
    return ops
      .map((o) => o.replace(/[\d.]+%/g, '').trim())
      .filter(Boolean)
      .some((o) => !o.startsWith('var(--he-') && o !== 'transparent');
  });

/** Blank out comments (keeping line breaks) so commented-out values do not count. */
const stripComments = (src) => src.replace(/\/\*[\s\S]*?\*\//g, (c) => c.replace(/[^\n]/g, ' '));

const walk = (dir, ext, out = []) => {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const p = path.join(dir, name);
    if (statSync(p).isDirectory()) walk(p, ext, out);
    else if (name.endsWith(ext)) out.push(p);
  }
  return out;
};

const offenders = [];
const escapes = [];
const rel = (p) => path.relative(root, p);

for (const file of scanDirs.flatMap((d) => walk(d, '.css'))) {
  const raw = readFileSync(file, 'utf8').split('\n');
  const code = stripComments(readFileSync(file, 'utf8')).split('\n');
  code.forEach((line, i) => {
    const where = `${rel(file)}:${i + 1}: ${raw[i].trim()}`;
    const escaped = raw[i].includes('tokens-ok');
    if (escaped) escapes.push(where);
    // Functional/hex literals outside color-mix, or a color-mix over non-token operands.
    const withoutMix = colorMixBodies(line).reduce((l, body) => l.replace(body, ''), line);
    if (LITERAL.test(withoutMix) || badColorMix(line)) {
      offenders.push(where + (escaped ? '   (tokens-ok does not excuse a colour literal)' : ''));
      return;
    }
    // Named colours: declaration values only (skip selectors and at-rule preludes).
    if (escaped) return;
    const decls = [...line.matchAll(/(?:^|[{;])\s*(?:--)?[\w-]+\s*:\s*([^;{}]*)(?=[;}]|$)/g)];
    const hits = decls.flatMap((d) => namedHits(d[1].replace(/(['"]).*?\1/g, '').replace(/url\([^)]*\)/g, '')));
    if (hits.length) offenders.push(`${where}   (named colour: ${hits.join(', ')})`);
  });
}

// Inline style objects in components and pages.
for (const file of scanDirs.flatMap((d) => walk(d, '.tsx'))) {
  const src = readFileSync(file, 'utf8');
  for (const m of src.matchAll(/style=\{\{/g)) {
    let depth = 0;
    let j = m.index + 'style='.length;
    for (; j < src.length; j++) {
      if (src[j] === '{') depth++;
      else if (src[j] === '}' && --depth === 0) break;
    }
    const body = src.slice(m.index, j + 1);
    const strings = [...body.matchAll(/(['"`])((?:\\.|(?!\1).)*)\1/g)].map((s) => s[2]);
    const bad = strings.filter((s) => LITERAL.test(s) || namedHits(s).length > 0);
    if (bad.length) {
      const lineNo = src.slice(0, m.index).split('\n').length;
      offenders.push(`${rel(file)}:${lineNo}: inline style colour literal ${bad.map((b) => `'${b}'`).join(', ')}`);
    }
  }
}

if (escapes.length) {
  console.warn(`[check-no-hex] ${escapes.length} tokens-ok escape(s):`);
  for (const e of escapes) console.warn('  ' + e);
}
if (offenders.length) {
  console.error('Raw colour values found (use --he-* tokens):');
  for (const o of offenders) console.error('  ' + o);
  process.exit(1);
}
console.log('[check-no-hex] component and page CSS and inline styles are token-clean');
